class Solution {
public:
    int numberOfSubstrings(string s) {
        int n = s.size();
        int cnt[3] = {0, 0, 0};
        int right = 0;
        int ans = 0;
        for (int left = 0; left < n; left++) {
            while (right < n && (cnt[0] == 0 || cnt[1] == 0 || cnt[2] == 0)) {
                cnt[s[right] - 'a']++;
                right++;
            }
            if (cnt[0] > 0 && cnt[1] > 0 && cnt[2] > 0) {
                ans += n - right + 1;
            }
            cnt[s[left] - 'a']--;
        }
        return ans;
    }
};
